-- Escalate repeat-login and administrator/session anomalies as thresholds increase.
create or replace function private.cr_security_emit_alert(p_type text,p_severity text,p_title text,p_summary text,p_source text,p_subject_key text,p_details jsonb,p_dedupe_key text)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid; begin
 insert into public.podcasting_security_alerts(alert_type,severity,title,summary,source,subject_key,details,dedupe_key) values(p_type,p_severity,p_title,p_summary,p_source,p_subject_key,coalesce(p_details,'{}'::jsonb),p_dedupe_key)
 on conflict(dedupe_key) where status in('open','acknowledged') do update set updated_at=now(),details=excluded.details,summary=excluded.summary,title=excluded.title,severity=case when excluded.severity='critical' then 'critical' else public.podcasting_security_alerts.severity end returning id into v_id;
 if p_severity in('high','critical') then insert into public.podcasting_security_notification_outbox(alert_id,recipient_email) select v_id,u.email from auth.users u where u.email is not null and (lower(coalesce(u.raw_app_meta_data->>'role','')) in('admin','owner','super_admin') or exists(select 1 from public.members m where m.user_id=u.id and lower(coalesce(m.status,''))='active' and lower(coalesce(m.role,'')) in('admin','owner','super_admin')) or exists(select 1 from public.hub_admins h where h.user_id=u.id and lower(coalesce(h.role,'')) in('admin','owner','super_admin')) or exists(select 1 from public.cr_admins a where a.user_id=u.id and a.is_active and lower(coalesce(a.role,'')) in('admin','owner','super_admin'))) on conflict(alert_id,recipient_email) do nothing; end if; return v_id; end $$;
create or replace function private.cr_security_failed_login_alert() returns trigger language plpgsql security definer set search_path='' as $$
declare v_count integer; v_severity text; begin select count(*) into v_count from public.podcasting_auth_failure_events where identifier_hash=new.identifier_hash and attempted_at>now()-interval '15 minutes'; if v_count>=5 then v_severity:=case when v_count>=10 then 'critical' else 'high' end; perform private.cr_security_emit_alert('repeated_failed_logins',v_severity,case when v_count>=10 then 'Critical failed-login burst' else 'Repeated failed password sign-ins' end,v_count||' failed password sign-ins were recorded for one privacy-preserving identifier fingerprint within 15 minutes.','podcasting_auth_failure_events',left(new.identifier_hash,16),jsonb_build_object('failure_count',v_count,'window_minutes',15,'identifier_fingerprint',left(new.identifier_hash,16)),'failed-login:'||left(new.identifier_hash,32)); end if; return new; end $$;
create or replace function private.cr_security_admin_activity_alert() returns trigger language plpgsql security definer set search_path='' as $$
declare v_count integer; v_severity text; begin select count(*) into v_count from public.cr_podcast_admin_audit where admin_user_id=new.admin_user_id and created_at>now()-interval '10 minutes'; if v_count>=15 then v_severity:=case when v_count>=30 then 'critical' else 'high' end; perform private.cr_security_emit_alert('unusual_admin_activity',v_severity,case when v_count>=30 then 'Critical administrator activity spike' else 'Unusually high administrator activity' end,v_count||' administrator audit events were recorded for one administrator within 10 minutes.','cr_podcast_admin_audit',new.admin_user_id::text,jsonb_build_object('event_count',v_count,'window_minutes',10,'admin_user_id',new.admin_user_id),'admin-activity:'||new.admin_user_id::text||':'||date_trunc('hour',now())::text); end if; return new; end $$;
create or replace function public.podcasting_security_monitor_scan() returns jsonb language plpgsql security definer set search_path='' as $$
declare v_row record; v_alerts integer; v_critical integer; begin if auth.uid() is null or not coalesce(private.crowrules_is_admin_impl(),false) then raise exception 'ADMIN_AUTH_REQUIRED' using errcode='42501'; end if;
 for v_row in select user_id,count(*) session_count from auth.sessions group by user_id having count(*)>=8 loop perform private.cr_security_emit_alert('session_anomaly',case when v_row.session_count>=12 then 'critical' else 'medium' end,case when v_row.session_count>=12 then 'Critical session count anomaly' else 'Unusually high active session count' end,v_row.session_count||' active sessions are associated with one account. Confirm whether these sessions are expected.','auth.sessions',v_row.user_id::text,jsonb_build_object('session_count',v_row.session_count,'user_id',v_row.user_id),'session-anomaly:'||v_row.user_id::text||':'||date_trunc('hour',now())::text); end loop;
 for v_row in select identifier_hash,count(*) failure_count from public.podcasting_auth_failure_events where attempted_at>now()-interval '15 minutes' group by identifier_hash having count(*)>=5 loop perform private.cr_security_emit_alert('repeated_failed_logins',case when v_row.failure_count>=10 then 'critical' else 'high' end,case when v_row.failure_count>=10 then 'Critical failed-login burst' else 'Repeated failed password sign-ins' end,v_row.failure_count||' failed password sign-ins were recorded for one identifier fingerprint in 15 minutes.','podcasting_auth_failure_events',left(v_row.identifier_hash,16),jsonb_build_object('failure_count',v_row.failure_count,'identifier_fingerprint',left(v_row.identifier_hash,16)),'failed-login:'||left(v_row.identifier_hash,32)); end loop;
 select count(*) into v_alerts from public.podcasting_security_alerts where status in('open','acknowledged'); select count(*) into v_critical from public.podcasting_security_alerts where severity='critical' and status in('open','acknowledged'); return jsonb_build_object('open_alerts',v_alerts,'critical_alerts',v_critical,'scan_at',now()); end $$;